import {spellingModeGuide,learningBadge} from './learning-polish.js';
import {AirSliceAudio} from './air-slice-audio.js';
import {spellingCover} from './spelling-art.js';
import {DB,player,save,uid,unlock,commitRound} from './data.js';
import {audio,fx,muteBackground} from './audio.js';
import {createInstructionGate} from './game-instructions.js';
import {SPELLING_WORDS} from './spelling-words.js';
import {SPELLING_LEVELS,SPELLING_TURN_WEIGHTS,SPELLING_MODES,SPELLING_DEFAULTS,nikoWordEligible,normalizeSpellingSettings,SpellingRun,freshSpelling,poolProgress,encounterWord,recordSpellingAnswer,redactWord} from './spelling-core.js';
import {WritingBoard} from './spelling-board.js';
import {SpellingSpeech} from './spelling-speech.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const name=s=>s[0].toUpperCase()+s.slice(1);

export function openSpelling(host,{exit,notify=()=>{},ask=async()=>true,initialPage='setup',words=SPELLING_WORDS,speechFactory=o=>new SpellingSpeech(o),runFactory=o=>new SpellingRun(o)}={}){
 const q=s=>host.querySelector(s),account=id=>{const p=player(id);if(!p.spelling){p.spelling=freshSpelling();const own=p.name.toLowerCase();if(SPELLING_LEVELS.includes(own))p.spelling.settings.pool=own;}return p.spelling;};let ids=[DB.active,DB.profiles.find(p=>p.id!==DB.active)?.id],config=normalizeSpellingSettings(account(DB.active).settings),pools=[config.pool||'niko',account(ids[1]||ids[0]).settings.pool||'roxy'],page='setup',phase='setup',runs=[],boards=[],turn=0,sessionId='',paused=false,disposed=false,committed=false,teamStreak=0,teamBest=0,teamBonus=0,raf,last=performance.now(),focused=0,activeTheme='forest';
 if(config.partner&&config.partner!==ids[0]&&player(config.partner)){ids[1]=config.partner;pools[1]=account(ids[1]).settings.pool;}const sound=new AirSliceAudio();const speech=speechFactory({volume:config.speech,rate:config.rate,voiceId:config.voiceId,onVoicesChanged:()=>{if(!disposed)renderVoicePicker();},onStatus:message=>{const e=q('#spellSpeechStatus');if(e)e.textContent=message;host.querySelectorAll('[data-spell-voice-status]').forEach(n=>n.textContent=message);}}),gate=createInstructionGate({game:'spelling',onBack:exit,onReview:()=>pause(true)});muteBackground(true);
 const two=()=>config.layout!=='solo',shared=()=>config.layout==='coop',alternating=()=>config.layout==='turns'||shared(),strictTurns=()=>config.layout==='turns';
 const persist=()=>{config.partner=ids[1];account(ids[0]).settings={...config,pool:pools[0]};if(two()&&ids[1])account(ids[1]).settings.pool=pools[1];save();};
 function destroyBoards(){boards.forEach(b=>b.dispose());boards=[];}
 function header(){return `<header class="spell-header"><button data-spell-exit>← ARCADE</button><div><small>WORDS OPEN WORLDS</small><h1>Spelling Adventure<span>✦</span></h1></div><nav><button id="spellSetup">SETUP</button><button id="spellRecords">PROGRESS</button><button id="spellPause" ${page==='play'?'':'hidden'}>Ⅱ PAUSE</button><button id="spellFull" aria-label="Fullscreen">⛶</button></nav></header>`;}
 function wireHeader(){q('[data-spell-exit]').onclick=()=>leave(exit);q('#spellSetup').onclick=()=>leave(setup);q('#spellRecords').onclick=()=>leave(records);q('#spellPause').onclick=()=>pause(!paused);q('#spellFull').onclick=()=>{const r=q('.spell-room');if(document.fullscreenElement)document.exitFullscreen?.();else r.requestFullscreen?.().catch(()=>notify('Use F11 for browser fullscreen.'));};}
 async function leave(next){pause(true);if(page==='play'&&!['results','setup'].includes(phase)&&!await ask('Leave this spelling adventure?','Word practice is saved. This unfinished round will not add a high score.'))return;speech.cancel();destroyBoards();next();}
 const profiles=selected=>DB.profiles.map(p=>`<option value="${p.id}" ${p.id===selected?'selected':''}>${esc(p.name)}</option>`).join('');
 function setup(){speech.voiceId=config.voiceId;page='setup';phase='setup';paused=false;sound.quiet();speech.cancel();destroyBoards();host.innerHTML=`<section class="spell-room">${header()}<div class="spell-setup"><section class="spell-intro"><span class="spell-kicker">A LITTLE CURIOSITY. A WORLD OF WORDS.</span><h2>Listen.<br>Write.<br><em>Discover.</em></h2><div class="spell-cover">${spellingCover()}</div><p>Practice with your finger. Type your answer. Let every new word take you somewhere.</p><div class="spell-pool-cards">${SPELLING_LEVELS.map(p=>`<button data-spell-pool="${p}" class="${p===pools[0]?'selected':''}" style="--spell-color:${{niko:'#70a57f',roxy:'#6c95bd',kelly:'#9981bd'}[p]}"><span>${{niko:'🌱',roxy:'🌊',kelly:'✨'}[p]}</span><b>${name(p)}</b><small>${(p==='niko'?words[p].filter(nikoWordEligible):words[p]).length.toLocaleString()} ${p==='niko'?'words · 3–6 letters':'words'}</small></button>`).join('')}</div><small>Master a word with three correct answers without hints across three separate adventures.</small></section><section class="spell-options"><span class="spell-kicker">CHOOSE YOUR NEXT CHAPTER</span><h3>Ready for a word quest?</h3><label>Player 1<select id="spellP1">${profiles(ids[0])}</select></label><label>Play together<select id="spellLayout">${[['solo','Solo adventure'],['turns','Two players · take turns'],['split','Two players · simultaneous'],['coop','Co-op · shared board & score']].map(([v,n])=>`<option value="${v}" ${config.layout===v?'selected':''}>${n}</option>`).join('')}</select></label>${two()?`<div class="spell-form-grid"><label>Player 2<select id="spellP2">${profiles(ids[1])}</select></label><label>Player 2 word pool<select id="spellPool2">${SPELLING_LEVELS.map(p=>`<option value="${p}" ${p===pools[1]?'selected':''}>${name(p)}</option>`).join('')}</select></label></div>`:''}<div class="spell-modes">${Object.entries(SPELLING_MODES).map(([v,n])=>`<button data-spell-mode="${v}" class="${config.mode===v?'selected':''}"><b>${n}</b><span>${{bee:'Hear it. Type it.',builder:'Arrange the letter tiles.',missing:'Find the missing pieces.',sprint:'Race your own thinking.',survival:'Three hearts. Keep going.'}[v]}</span></button>`).join('')}</div><label class="spell-check"><input id="spellPractice" type="checkbox" ${config.practice?'checked':''}>Practice Missed Words</label><details class="spell-settings"><summary>Audio, round & whiteboard settings</summary>${settingsFields()}</details><p class="spell-fairness">${two()?(strictTurns()?'One word each, then swap! Each player completes '+config.words+' words. Niko ×1, Roxy ×1.25 and Kelly ×1.5 points reward harder trails. Sprint gives each word its own time window; Survival records hearts while both finish equal turns.':'Each player uses their own word pool, history and streak. Speech is queued so voices never overlap.'):'A new shuffled lineup every adventure. Recent words wait their turn.'}</p><button class="spell-primary" id="spellLaunch">LET’S PLAY <span>↗</span></button></section></div></section>`;wireHeader();q('#spellP1').onchange=e=>{ids[0]=e.target.value;config=normalizeSpellingSettings(account(ids[0]).settings);pools[0]=config.pool;setup();};q('#spellLayout').onchange=e=>{config.layout=e.target.value;setup();};if(two()){q('#spellP2').onchange=e=>{ids[1]=e.target.value;pools[1]=account(ids[1]).settings.pool;setup();};q('#spellPool2').onchange=e=>pools[1]=e.target.value;}host.querySelectorAll('[data-spell-pool]').forEach(b=>b.onclick=()=>{pools[0]=b.dataset.spellPool;config.pool=pools[0];setup();});host.querySelectorAll('[data-spell-mode]').forEach(b=>b.onclick=()=>{config.mode=b.dataset.spellMode;setup();});q('#spellPractice').onchange=e=>config.practice=e.target.checked;wireSettings();q('#spellLaunch').onclick=launch;}
 function settingsFields(){return `<section class="spell-voice-picker" data-spell-voice-picker></section><div class="spell-form-grid"><label>${strictTurns()?'Sprint time per word':'Sprint round length'}<select data-spell-setting="seconds">${[30,60,90,120].map(n=>`<option ${n===+config.seconds?'selected':''}>${n}</option>`).join('')}</select></label><label>${strictTurns()?'Words per player':'Words per adventure'}<select data-spell-setting="words">${[10,15,20].map(n=>`<option ${n===+config.words?'selected':''}>${n}</option>`).join('')}</select></label>${[['speech','Speech volume',0,1,.05],['rate','Speech speed',.6,1.2,.05],['sound','Sound effects',0,1,.05],['music','Music volume',0,.5,.05],['thickness','Pen thickness',2,16,1]].map(([id,n,min,max,step])=>`<label>${n}<input type="range" data-spell-setting="${id}" min="${min}" max="${max}" step="${step}" value="${config[id]}"></label>`).join('')}${[['untimed','Untimed Sprint'],['hints','Allow hints'],['board','Show writing board'],['lines','Lined paper'],['autoClear','Auto-Clear Writing Area After Each Word']].map(([id,n])=>`<label class="spell-check"><input type="checkbox" data-spell-setting="${id}" ${config[id]?'checked':''}>${n}</label>`).join('')}</div>`;}
 function wireSettings(){renderVoicePicker();host.querySelectorAll('[data-spell-setting]').forEach(e=>e.onchange=()=>{const k=e.dataset.spellSetting;config[k]=e.type==='checkbox'?e.checked:+e.value;speech.volume=DB.settings.muted?0:config.speech;speech.rate=config.rate;sound.sound=config.sound;sound.music=config.music;boards.forEach(b=>{b.width=config.thickness;b.canvas.parentElement.classList.toggle('unlined',!config.lines);});persist();});}
 function renderVoicePicker(){const choices=speech.voiceChoices?.()||[];for(const root of host.querySelectorAll('[data-spell-voice-picker]')){const missing=config.voiceId&&!choices.some(v=>v.id===config.voiceId);let preview=0;root.innerHTML=`<h4>CHOOSE YOUR SPELLING VOICE</h4><p>Female · American English · ${choices.length} of 3 voices available</p><div class="spell-voice-options"><label>Voice<select data-spell-voice-choice aria-label="Spelling voice"><option value="">Automatic · best available</option>${missing?`<option value="${esc(config.voiceId)}" selected>Saved voice unavailable · automatic fallback</option>`:''}${choices.map((v,i)=>`<option value="${esc(v.id)}" ${config.voiceId===v.id?'selected':''}>${i+1} · ${esc(v.name)}</option>`).join('')}</select></label><button type="button" data-spell-voice-preview>▶ TRY THIS VOICE</button></div><small>${choices.length===3?'Choose the clearest voice for you. Your choice is remembered.':choices.length?'Showing the matching voices your browser provides. Your choice is remembered.':'No named female American English voices are listed here. Automatic requests the browser’s American English voice.'} Word unclear? Try another voice, Say It Slowly or Hear Sentence.</small><p data-spell-voice-status role="status"></p>`;root.querySelector('[data-spell-voice-choice]').onchange=e=>{preview++;root.querySelector('[data-spell-voice-status]').textContent='Voice selected. Press Try This Voice to listen.';config.voiceId=e.target.value;speech.voiceId=config.voiceId;speech.setVoice?.(config.voiceId);persist();};root.querySelector('[data-spell-voice-preview]').onclick=()=>{const generation=++preview,status=root.querySelector('[data-spell-voice-status]');status.textContent=DB.settings.muted?'The arcade is muted. Unmute to hear the sample.':'Playing a voice sample…';speech.volume=DB.settings.muted?0:config.speech;speech.rate=config.rate;Promise.resolve(speech.speak('A bright star lights up the sky.',{replace:true,rate:config.rate})).then(ok=>{if(!disposed&&status.isConnected&&generation===preview)status.textContent=DB.settings.muted?'The arcade is muted. Unmute to hear the sample.':ok?'Sample finished. Choose the clearest voice for you.':'This voice could not play here. Try another choice or Automatic.';});};}}
 function context(){return{players:ids.slice(0,two()?2:1).map(id=>player(id).name),difficulty:pools.slice(0,two()?2:1).map(p=>name(p)+(p==='niko'&&!config.practice?' · 3–6 letters':'')).join(' & '),mode:config.mode,modeLabel:SPELLING_MODES[config.mode]+' · '+config.layout+(config.practice?' · Missed words':''),coop:shared(),words:config.words,seconds:config.seconds,untimed:config.untimed,layout:config.layout};}
 function launch(){if(two()&&(!ids[1]||ids[0]===ids[1])){notify('Choose two different player profiles.');return;}config.pool=pools[0];persist();DB.active=ids[0];save();gate.show(context(),start);}
 function start(){speech.voiceId=config.voiceId;sound.sound=config.sound;sound.music=config.music;sound.muted=DB.settings.muted;sound.enable().then(()=>{if(!disposed&&phase==='play'&&!paused)sound.playMusic();}).catch(()=>{});destroyBoards();speech.cancel();sessionId=uid();turn=0;teamStreak=0;teamBest=0;teamBonus=0;committed=false;paused=false;page='play';phase='play';activeTheme=['forest','space','ocean','candy','mountain','dinosaur'][crypto.getRandomValues(new Uint32Array(1))[0]%6];runs=ids.slice(0,two()?2:1).map((id,i)=>{const state=account(id),progress=poolProgress(state,pools[i]);progress.sessions++;return runFactory({words:words[pools[i]],progress,pool:pools[i],mode:config.mode,sessionId,practice:!!config.practice,seconds:+config.seconds,untimed:config.untimed,turnBased:strictTurns(),deferStart:strictTurns(),target:shared()?Math.ceil(config.words/2):+config.words,onEncounter:e=>{encounterWord(progress,e.word,words[pools[i]].length);save();},onAnswer:f=>{recordSpellingAnswer(state,pools[i],f.word,{correct:f.correct,hinted:f.hinted,sessionId,category:f.entry.category});state.bestStreak=Math.max(state.bestStreak,runs[i]?.bestStreak||0);save();}});});if(strictTurns()){if(runs.some(r=>!r.deck.length)){notify('Both players need words in their selected practice lists. Try Spelling Bee without Practice Missed Words, or choose another word trail.');setup();return;}runs[0].next();}host.innerHTML=`<section class="spell-room theme-${activeTheme} ${strictTurns()?'spell-turns':''}">${header()}<div class="spell-game-top"><span>${SPELLING_MODES[config.mode]} · ${shared()?'TEAM ADVENTURE':config.layout==='split'?'PLAY TOGETHER':config.layout==='turns'?'TAKE TURNS':'YOUR WORD QUEST'}${config.practice?' · MISSED WORDS':''}</span><strong id="spellTeam"></strong><button id="spellSettingsButton">⚙ SETTINGS</button></div><div class="spell-players ${config.layout==='split'?'spell-split':''}">${runs.map((r,i)=>panel(i)).join('')}</div><p class="spell-speech-status" id="spellSpeechStatus" role="status">${speech.available?'Repeat Word says only the word. Choose a female American English voice in Settings, or try Say It Slowly and Hear Sentence.':'Speech is unavailable here. The definition, pattern and writing board still work.'}</p><div class="spell-overlay" id="spellOverlay" hidden></div></section>`;wireHeader();q('#spellSettingsButton').onclick=settings;boards=runs.map((r,i)=>new WritingBoard(q(`[data-spell-canvas="${i}"]`),{color:config.pen,width:config.thickness,lines:config.lines,canDraw:()=>enabled(i)&&!runs[i].feedback,onChange:()=>shareWriting(i)}));if(shared()&&boards[1])boards[1].operations=boards[0].operations;runs.forEach((r,i)=>wirePanel(i));showTurns();runs.forEach((r,i)=>{refresh(i);if(r.done)return;if(!alternating()||i===0)say(i,'word',true);});if(runs.every(r=>r.done))finish();last=performance.now();audio();}
 function panel(i){return `<section class="spell-player" data-spell-panel="${i}" style="--spell-player:${i?'#d08c69':'#6f94ad'}"><header><div><span>PLAYER ${i+1} · ${esc(player(ids[i]).name)}</span><b>${name(pools[i])}’s word trail${pools[i]==='niko'&&!config.practice?' · 3–6 letters':''}</b></div><strong data-spell-score="${i}">0</strong><small data-spell-status="${i}"></small></header><div class="spell-work"><div class="spell-word-meta"><span data-spell-number="${i}"></span><strong data-spell-time="${i}"></strong></div><div class="spell-prompt" data-spell-prompt="${i}"></div><div class="learning-guide">${learningBadge()}<p>${spellingModeGuide(config.mode)}</p></div><div class="spell-audio-buttons">${[['word','🔊 REPEAT WORD'],['slow','SAY IT SLOWLY'],['sentence','HEAR SENTENCE'],['definition','DEFINITION'],['hint','HINT']].map(([v,n])=>`<button data-spell-audio="${v}" data-player="${i}" ${v==='hint'&&!config.hints?'hidden':''}>${n}</button>`).join('')}</div><p class="spell-clue" data-spell-clue="${i}"></p><div class="spell-tile-bank" data-spell-tiles="${i}"></div><div class="spell-tile-slots" data-spell-slots="${i}"></div><form data-spell-form="${i}"><label>${config.mode==='missing'?'TYPE ONLY THE MISSING LETTERS':'OFFICIAL TYPED ANSWER'}<input data-spell-answer="${i}" autocomplete="off" autocorrect="off" autocapitalize="off" spellcheck="false" inputmode="none" aria-label="Player ${i+1} official spelling answer" ${config.mode==='builder'?'readonly':''}></label><button class="spell-primary" type="submit">SUBMIT ↗</button></form><div class="spell-keyboard">${['qwertyuiop','asdfghjkl','zxcvbnm'].map(row=>`<div>${[...row].map(k=>`<button data-spell-key="${k}" data-player="${i}" type="button">${k.toUpperCase()}</button>`).join('')}</div>`).join('')}<div><button data-spell-key="Backspace" data-player="${i}" type="button">⌫ BACKSPACE</button><button data-spell-key="Clear" data-player="${i}" type="button">CLEAR ANSWER</button></div></div><div class="spell-feedback" data-spell-feedback="${i}" role="status"></div></div><section class="spell-board ${config.lines?'':'unlined'}" data-spell-board="${i}" ${config.board?'':'hidden'}><div class="spell-board-heading"><div><b>YOUR THINKING SPACE</b><small>Write, sketch, wonder. Type to score.</small></div><button data-spell-board-close="${i}" aria-label="Hide writing board">−</button></div><canvas data-spell-canvas="${i}" aria-label="Player ${i+1} freehand practice whiteboard"></canvas><div class="spell-board-tools"><button data-spell-pen="${i}" class="selected">✎ PEN</button><button data-spell-eraser="${i}">ERASER</button><button data-spell-undo="${i}">↶ UNDO</button><button data-spell-clear="${i}">CLEAR BOARD</button><label>INK<input type="color" data-spell-color="${i}" value="${config.pen}"></label><label>SIZE<input type="range" data-spell-width="${i}" min="2" max="16" value="${config.thickness}"></label><button data-spell-lines="${i}">☷ LINES</button></div></section><button class="spell-restore-board" data-spell-board-open="${i}" ${config.board?'hidden':''}>✎ OPEN WRITING BOARD</button></section>`;}
 function enabled(i){return phase==='play'&&!paused&&!runs[i].done&&(!alternating()||i===turn);}
 function showTurns(){runs.forEach((r,i)=>{const p=q(`[data-spell-panel="${i}"]`);p.hidden=alternating()&&(phase==='handoff'||i!==turn);p.inert=!enabled(i);});const area=q('.spell-players');if(area)area.inert=paused||phase!=='play';boards.forEach(b=>b.redraw());}
 function lockAnswers(){runs.forEach((r,i)=>{const locked=!enabled(i)||!!r.feedback;q(`[data-spell-answer="${i}"]`).disabled=locked;q(`[data-spell-form="${i}"] button[type="submit"]`).disabled=locked;host.querySelectorAll(`[data-spell-key][data-player="${i}"],[data-spell-tile],[data-spell-slot]`).forEach(e=>{if(e.closest?.(`[data-spell-panel="${i}"]`))e.disabled=locked;});});}

 function wirePanel(i){const input=q(`[data-spell-answer="${i}"]`),b=boards[i];input.onfocus=()=>focused=i;input.oninput=()=>{if(enabled(i)&&!runs[i].feedback)runs[i].answer=input.value.replace(/[^a-zA-Z'-]/g,'').slice(0,40);else input.value=runs[i].answer;};q(`[data-spell-form="${i}"]`).onsubmit=e=>{e.preventDefault();submit(i);};host.querySelectorAll(`[data-spell-key][data-player="${i}"]`).forEach(e=>e.onclick=()=>{if(!enabled(i)||runs[i].feedback)return;focused=i;if(e.dataset.spellKey==='Clear'){runs[i].answer='';runs[i].placed=[];}else runs[i].key(e.dataset.spellKey);refreshAnswer(i);});host.querySelectorAll(`[data-spell-audio][data-player="${i}"]`).forEach(e=>e.onclick=()=>{if(enabled(i))say(i,e.dataset.spellAudio);});for(const [tool,k]of [['pen','pen'],['eraser','eraser']])q(`[data-spell-${tool}="${i}"]`).onclick=()=>{if(!enabled(i))return;b.tool=k;q(`[data-spell-pen="${i}"]`).classList.toggle('selected',k==='pen');q(`[data-spell-eraser="${i}"]`).classList.toggle('selected',k==='eraser');};q(`[data-spell-undo="${i}"]`).onclick=()=>{if(enabled(i))b.undo();};q(`[data-spell-clear="${i}"]`).onclick=()=>{if(enabled(i))b.clear();};q(`[data-spell-color="${i}"]`).oninput=e=>{b.color=e.target.value;config.pen=b.color;persist();};q(`[data-spell-width="${i}"]`).oninput=e=>{b.width=+e.target.value;config.thickness=b.width;persist();};q(`[data-spell-lines="${i}"]`).onclick=()=>{q(`[data-spell-board="${i}"]`).classList.toggle('unlined');config.lines=!q(`[data-spell-board="${i}"]`).classList.contains('unlined');persist();};q(`[data-spell-board-close="${i}"]`).onclick=()=>toggleBoard(i,false);q(`[data-spell-board-open="${i}"]`).onclick=()=>toggleBoard(i,true);}
 function shareWriting(i){if(shared()&&boards[1-i]){boards[1-i].operations=boards[i].operations;boards[1-i].redraw();}}
 function toggleBoard(i,visible){config.board=visible;q(`[data-spell-board="${i}"]`).hidden=!visible;q(`[data-spell-board-open="${i}"]`).hidden=visible;boards[i].redraw();persist();}
 function say(i,kind,automatic=false){const r=runs[i];if(!enabled(i)||!r.entry||r.done)return;speech.volume=DB.settings.muted?0:config.speech;speech.rate=config.rate;const clue=q(`[data-spell-clue="${i}"]`);if(kind==='hint'){if(!r.feedback)clue.textContent=r.hint();return;}if(kind==='definition'){clue.textContent=redactWord(r.entry.definition,r.entry.word);speech.speak(r.entry.definition,{replace:true});return;}const prefix=automatic&&runs.length>1?player(ids[i]).name+'. ':'';const word=r.entry.word==='i'?'I':r.entry.word;speech.speak(prefix+(kind==='sentence'?r.entry.sentence:word+'.'),{rate:kind==='slow'?Math.max(.5,Math.min(.75,config.rate*.85)):config.rate,replace:!automatic});}

 function refresh(i){const r=runs[i];if(!r.entry)return;q(`[data-spell-prompt="${i}"]`).textContent=r.prompt;q(`[data-spell-number="${i}"]`).textContent='WORD '+(r.index+1)+' · '+r.entry.category;q(`[data-spell-clue="${i}"]`).textContent=redactWord(r.entry.definition,r.entry.word);q(`[data-spell-feedback="${i}"]`).innerHTML='';q(`[data-spell-answer="${i}"]`).disabled=r.done;refreshAnswer(i);lockAnswers();updateHud();}
 function refreshAnswer(i){const r=runs[i];q(`[data-spell-answer="${i}"]`).value=r.answer;const bank=q(`[data-spell-tiles="${i}"]`),slots=q(`[data-spell-slots="${i}"]`);bank.hidden=slots.hidden=config.mode!=='builder';if(config.mode!=='builder')return;bank.innerHTML=r.tiles.filter(t=>!r.placed.includes(t.id)).map(t=>`<button data-spell-tile="${t.id}">${t.letter.toUpperCase()}</button>`).join('');slots.innerHTML=r.placed.map((id,j)=>`<button data-spell-slot="${j}">${r.tiles.find(t=>t.id===id).letter.toUpperCase()}</button>`).join('')||'<span>Tap tiles here, or drag to arrange.</span>';let drag=null;const setup=(root,selector,key)=>root.querySelectorAll(selector).forEach(e=>{e.onpointerdown=ev=>{if(!enabled(i)||r.feedback)return;ev.preventDefault();focused=i;e.setPointerCapture(ev.pointerId);drag={id:key==='tile'?+e.dataset.spellTile:r.placed[+e.dataset.spellSlot],from:key==='slot'?+e.dataset.spellSlot:null,x:ev.clientX,y:ev.clientY};};e.onpointermove=ev=>{if(!enabled(i)||r.feedback){drag=null;e.style.transform='';return;}if(drag){ev.preventDefault();e.style.transform=`translate(${ev.clientX-drag.x}px,${ev.clientY-drag.y}px)`;}};e.onpointerup=ev=>{if(!enabled(i)||r.feedback){drag=null;e.style.transform='';return;}if(!drag)return;const v=drag;drag=null;const rect=slots.getBoundingClientRect(),moved=Math.hypot(ev.clientX-v.x,ev.clientY-v.y)>10;if(key==='slot'&&!moved)r.removeTile(v.from);else if(!moved||ev.clientY>=rect.top-25&&ev.clientY<=rect.bottom+25)r.placeTile(v.id,Math.floor((ev.clientX-rect.left)/Math.max(38,rect.width/Math.max(1,r.placed.length+1))));refreshAnswer(i);};e.onpointercancel=e.onlostpointercapture=()=>{drag=null;e.style.transform='';};});setup(bank,'[data-spell-tile]','tile');setup(slots,'[data-spell-slot]','slot');}
 function submit(i){if(!enabled(i)||runs[i].feedback)return;const f=runs[i].submit();if(!f){notify('Type or arrange an answer first.');return;}showFeedback(i,f);}
 function showFeedback(i,f){const r=runs[i];speech.cancel();if(config.sound&&!DB.settings.muted)sound.fx(f.correct?'combo':'miss',runs[i].streak);if(shared()){teamStreak=f.correct?teamStreak+1:0;teamBest=Math.max(teamBest,teamStreak);teamBonus+=({3:50,5:100,10:250}[teamStreak]||0);}const e=q(`[data-spell-feedback="${i}"]`);e.classList.toggle('correct',f.correct);e.innerHTML=`<strong>${f.correct?'Beautiful spelling! +'+f.points:f.timedOut?'Time’s up — let’s learn this word.':'A word to grow with.'}</strong><div class="spell-letter-feedback">${f.diff.map(v=>`<span class="${v.kind}">${esc(v.expected||v.typed)}${v.kind==='extra'?'<small>extra</small>':''}</span>`).join('')}</div>${!f.correct?`<p>You typed <b>${esc(f.typed)}</b>. Correct word: <b>${esc(f.word)}</b>. ${esc(f.entry.pattern)}<br>${esc(f.entry.sentence)}</p><small>Green letters match. Amber letters changed or were missing. Crossed-out letters were extra.</small><button data-spell-rehear>🔊 HEAR IT AGAIN</button>`:`<p>${strictTurns()?'×'+f.multiplier+' trail points · ':''}${r.streak} in a row${f.hinted?' · hint used':' · no hints'}. ${esc(f.entry.pattern)}</p>`}<button class="spell-primary" data-spell-next>${strictTurns()?(runs.every(v=>v.correct+v.wrong>=config.words)?'SEE OUR RESULTS →':'NEXT PLAYER →'):r.hearts===0?'SEE MY ADVENTURE':'NEXT WORD →'}</button>`;e.querySelector('[data-spell-next]').onclick=()=>next(i);if(e.querySelector('[data-spell-rehear]'))e.querySelector('[data-spell-rehear]').onclick=()=>{if(enabled(i))speech.speak(f.word,{replace:true});};lockAnswers();updateHud();}
 function next(i){if(!enabled(i)||!runs[i].feedback)return;const r=runs[i];speech.cancel();boards.forEach(b=>b.cancel());
  if(strictTurns()){
   if(r.correct+r.wrong>=r.target)r.done=true;
   if(config.autoClear)boards[i].clear();
   if(runs.every(v=>v.correct+v.wrong>=v.target)){runs.forEach(v=>v.done=true);finish();return;}
   handoff(1-i);return;
  }
  r.next();r.wordAt=r.clock;if(config.autoClear)boards[i].clear();if(alternating()){if(shared()){turn=1-turn;if(runs[turn].done)turn=i;}showTurns();}refresh(i);if(runs.every(r=>r.done)){finish();return;}const current=alternating()?turn:i;if(!runs[current].done){refresh(current);say(current,'word',true);}
 }
 function handoff(nextPlayer){speech.cancel();sound.quiet();boards.forEach(b=>b.cancel());turn=nextPlayer;phase='handoff';showTurns();lockAnswers();q('#spellPause').disabled=true;q('#spellSettingsButton').disabled=true;const o=q('#spellOverlay');o.hidden=false;o.setAttribute('role','dialog');o.setAttribute('aria-modal','true');o.setAttribute('aria-labelledby','spellHandoffTitle');o.innerHTML=`<section class="spell-handoff"><span>PASS THE SCREEN · WORD & CLOCK WAITING</span><h2 id="spellHandoffTitle">Player ${turn+1} — ${esc(player(ids[turn]).name)}, you’re up!</h2><p>Word ${runs[turn].correct+runs[turn].wrong+1} of ${runs[turn].target} · ${name(pools[turn])} trail · ×${SPELLING_TURN_WEIGHTS[pools[turn]]} points</p><p>Your word stays hidden and silent until you’re ready.<br>${config.autoClear?'A fresh writing space awaits.':'Your own writing is kept separate and will return.'}</p><button class="spell-primary" id="spellHandoff">READY!</button><button id="spellHandoffExit">← ARCADE</button></section>`;
  q('#spellHandoffExit').onclick=()=>leave(exit);q('#spellHandoff').onclick=()=>{if(phase!=='handoff')return;const r=runs[turn];if(!r.entry||r.feedback)r.next();phase='play';paused=false;o.hidden=true;o.removeAttribute('role');o.removeAttribute('aria-modal');q('#spellPause').disabled=false;q('#spellSettingsButton').disabled=false;showTurns();refresh(turn);focused=turn;q(`[data-spell-answer="${turn}"]`).focus();sound.playMusic();say(turn,'word',true);last=performance.now();};q('#spellHandoff').focus();updateHud();
 }

 function updateHud(){if(page!=='play')return;runs.forEach((r,i)=>{q(`[data-spell-score="${i}"]`).textContent=r.score;q(`[data-spell-status="${i}"]`).textContent=r.correct+' correct · '+r.accuracy+'% · streak '+r.streak;q(`[data-spell-time="${i}"]`).textContent=config.mode==='sprint'&&!config.untimed?Math.ceil(r.remaining/1000)+'s':config.mode==='survival'?'♥'.repeat(r.hearts)+'♡'.repeat(3-r.hearts):(r.correct+r.wrong)+' / '+r.target;});q('#spellTeam').textContent=strictTurns()?'PLAYER '+(turn+1)+' · '+player(ids[turn]).name+' · TURN '+(Math.min(config.words*2,runs.reduce((n,r)=>n+r.correct+r.wrong,0)+(phase==='handoff'||!runs[turn].feedback?1:0)))+' / '+(config.words*2):shared()?runs.reduce((s,r)=>s+r.score,teamBonus)+' TEAM POINTS · STREAK '+teamStreak:'';}
 function pause(value){if(page!=='play'||phase==='results'||phase==='handoff')return;paused=value;if(value)sound.quiet();else sound.playMusic();speech.cancel();boards.forEach(b=>b.cancel());const o=q('#spellOverlay');o.hidden=!value;q('#spellPause').textContent=value?'▶ RESUME':'Ⅱ PAUSE';showTurns();lockAnswers();if(value){o.innerHTML='<section><span>THINKING TIME · CLOCK STOPPED</span><h2>Take a little breather.</h2><button class="spell-primary" id="spellResume">RESUME →</button><button id="spellRestart">↻ RESTART ROUND</button></section>';q('#spellResume').onclick=()=>pause(false);q('#spellRestart').onclick=()=>{start();};}last=performance.now();}
 function settings(){if(phase==='handoff')return;pause(true);const o=q('#spellOverlay');o.innerHTML=`<section class="spell-settings-card"><h2>Make it yours.</h2>${settingsFields()}<p>Round length, hints and timed options apply on the next round. Audio and pen settings apply now.</p><button class="spell-primary" id="spellSettingsDone">DONE · BACK TO PAUSE</button></section>`;const locked=['seconds','words','untimed','hints'];o.querySelectorAll('[data-spell-setting]').forEach(e=>e.disabled=locked.includes(e.dataset.spellSetting));wireSettings();q('#spellSettingsDone').onclick=()=>{runs.forEach((r,i)=>toggleBoard(i,config.board));pause(true);};}
 function finish(){if(committed)return;committed=true;phase='results';paused=true;showTurns();lockAnswers();sound.quiet();sound.fx('win');speech.cancel();boards.forEach(b=>b.cancel());const summaries=runs.map(r=>r.summary()),versus=two()&&!shared(),compare=versus?(summaries[0].score-summaries[1].score||summaries[0].accuracy-summaries[1].accuracy):0,teamScore=runs.reduce((s,r)=>s+r.score,teamBonus),entries=summaries.map((r,i)=>({id:ids[i],score:shared()?teamScore:r.score,hits:r.correct,errors:r.wrong,accuracy:r.accuracy,duration:r.clock/1000,completed:true,soloWin:r.correct>0,details:{...r,pool:pools[i],sessionId,teamIds:shared()?ids.slice(0,2):undefined,teamStreak:teamBest,practice:!!config.practice}})),opts={game:'spelling',difficulty:SPELLING_LEVELS.indexOf(pools[0])+1,learn:true,mode:versus?'versus':'solo',ruleset:strictTurns()?'spelling-turns-v2':'spelling-v1',levelId:config.mode,competition:config.layout,challengeKey:[...pools.slice(0,two()?2:1),config.practice?'review':'variety',config.hints?'hints':'no-hints',config.mode==='sprint'&&!config.untimed?config.seconds+'s':config.words+'words'].join(':'),pointsEligible:!config.practice,winnerId:versus?compare?ids[compare>0?0:1]:null:undefined};if(entries.some(e=>e.hits+e.errors>0)){if(shared())entries.forEach(e=>commitRound([e],{...opts,difficulty:SPELLING_LEVELS.indexOf(e.details.pool)+1,winnerId:undefined}));else commitRound(entries,opts);}
 summaries.forEach((r,i)=>{const p=player(ids[i]),s=account(ids[i]);s.games++;s.bestScore=Math.max(s.bestScore,r.score);s.bestStreak=Math.max(s.bestStreak,r.bestStreak);const mastered=Object.values(s.pools).reduce((n,p)=>n+Object.values(p.words).filter(w=>w.mastered).length,0);if(s.correct>=10)unlock(p,'spell-ten');if(r.correct>=10&&r.wrong===0)unlock(p,'spell-perfect');if(s.correct>=100)unlock(p,'spell-super');if(mastered>=100)unlock(p,'spell-master100');if(mastered>=500)unlock(p,'spell-master500');if(config.mode==='sprint'&&!config.untimed&&r.correct>=10)unlock(p,'spell-speed');if(r.bestStreak>=10)unlock(p,'spell-streak');if(config.practice&&r.correct>=5)unlock(p,'spell-comeback');if(shared()&&teamBest>=5)unlock(p,'spell-team');if(r.correct>=20)unlock(p,'spell-'+pools[i]);});save();const o=q('#spellOverlay');o.hidden=false;o.innerHTML=`<section class="spell-results"><span>ANOTHER CHAPTER · PROGRESS SAVED</span><h2>${shared()?'Word explorers, together!':versus?compare?esc(player(ids[compare>0?0:1]).name)+' wins!':'A thoughtful tie.':'Look how far you’ve come.'}</h2>${shared()?`<strong>${teamScore} team points · best team streak ${teamBest}</strong>`:''}<div>${summaries.map((r,i)=>`<article><b>${esc(player(ids[i]).name)} · ${name(pools[i])}</b><strong>${r.score}</strong>${strictTurns()?`<small>${r.baseScore} base points ×${r.multiplier} trail weight · ${r.attempted} turns</small>`:''}<p>${r.correct} correct · ${r.wrong} to practice<br>${r.accuracy}% accuracy · best streak ${r.bestStreak}</p>${runs[i].reason?`<small>${esc(runs[i].reason)}</small>`:''}</article>`).join('')}</div><button class="spell-primary" id="spellAgain">PLAY AGAIN →</button><button id="spellResultProgress">MY PROGRESS</button><button id="spellResultSetup">SETUP</button></section>`;q('#spellAgain').onclick=launch;q('#spellAgain').focus();q('#spellResultProgress').onclick=records;q('#spellResultSetup').onclick=setup;}
 function records(){page='records';phase='records';sound.quiet();speech.cancel();destroyBoards();host.innerHTML=`<section class="spell-room">${header()}<div class="spell-progress"><span class="spell-kicker">EVERY WORD IS A STEP FORWARD</span><h2>Your growing word garden.</h2><p>Mastery means three correct answers without hints in three separate adventures. A new mistake marks a word for review. Handwriting is practice; only submitted spelling counts.</p><div class="spell-progress-cards">${DB.profiles.map(p=>{const s=account(p.id),poolRows=SPELLING_LEVELS.map(pool=>{const pr=poolProgress(s,pool),all=Object.values(pr.words),mastered=all.filter(w=>w.mastered).length,missed=Object.entries(pr.words).filter(([w,v])=>v.reviewNeeded).sort((a,b)=>b[1].missed-a[1].missed).slice(0,8);return `<section><h4>${name(pool)}</h4><strong>${mastered} mastered</strong><small>${all.length} words explored · ${pr.history.length} recent</small><p>${missed.length?'Practice next: '+missed.map(([w])=>esc(w)).join(', '):'No words waiting for review.'}</p></section>`;}).join('');return `<article><h3>${esc(p.name)}</h3><p>${s.games} adventures · ${s.correct} correct · ${s.correct+s.wrong?s.correct/(s.correct+s.wrong)*100|0:0}% accuracy<br>Best streak ${s.bestStreak} · personal best ${s.bestScore}</p>${poolRows}<details><summary>Performance by category</summary>${Object.entries(s.categories||{}).map(([k,v])=>`<p>${esc(k)}: ${v.correct} correct / ${v.correct+v.wrong} attempted</p>`).join('')||'<p>Your first word will start your record.</p>'}</details></article>`;}).join('')}</div><h3>Adventure records</h3><div class="spell-record-filters"><select id="spellBoardMode" aria-label="Record game mode">${Object.entries(SPELLING_MODES).map(([v,n])=>`<option value="${v}">${n}</option>`).join('')}</select><select id="spellBoardPool" aria-label="Record word pool">${SPELLING_LEVELS.map(p=>`<option>${name(p)}</option>`).join('')}</select><select id="spellBoardLayout" aria-label="Record players">${['solo','turns','split','coop'].map(v=>`<option>${v}</option>`).join('')}</select></div><label id="spellRulesLabel">Scoring rules<select id="spellBoardRules"><option value="spelling-turns-v2">Difficulty-adjusted turns</option><option value="spelling-v1">Original spelling rules</option></select></label><div id="spellRecordRows"></div><button class="spell-primary" id="spellProgressPlay">BACK TO ADVENTURE →</button></div></section>`;wireHeader();const render=()=>{const turns=q('#spellBoardLayout').value==='turns';q('#spellRulesLabel').hidden=!turns;let rows=DB.profiles.flatMap(p=>p.results.filter(r=>r.game==='spelling'&&(!turns||r.ruleset===q('#spellBoardRules').value)&&r.levelId===q('#spellBoardMode').value&&r.details?.pool===q('#spellBoardPool').value.toLowerCase()&&r.competition===q('#spellBoardLayout').value).map(r=>({p,r}))).sort((a,b)=>b.r.score-a.r.score).slice(0,60);if(q('#spellBoardLayout').value==='coop'){const seen=new Set();rows=rows.filter(({r})=>{if(seen.has(r.details.sessionId))return false;seen.add(r.details.sessionId);return true;});}rows=rows.slice(0,30);q('#spellRecordRows').innerHTML=rows.length?`<table><thead><tr><th>PLAYER</th><th>SCORE</th><th>ACCURACY</th><th>RULES</th></tr></thead><tbody>${rows.map(({p,r})=>`<tr><td>${r.details.teamIds?r.details.teamIds.map(id=>esc(player(id)?.name||'Player')).join(' & '):esc(p.name)}</td><td>${r.score}</td><td>${r.accuracy}%</td><td>${esc(r.challengeKey)}</td></tr>`).join('')}</tbody></table>`:'<p>A fresh trail. Complete an adventure to set a record.</p>';};for(const id of ['Mode','Pool','Layout','Rules'])q('#spellBoard'+id).onchange=render;render();q('#spellProgressPlay').onclick=setup;}
 function key(e){if(page==='play'&&phase==='handoff'){if(e.key==='Tab'){e.preventDefault();const ready=q('#spellHandoff'),back=q('#spellHandoffExit');(document.activeElement===ready?back:ready).focus();}if(e.repeat&&(e.key==='Enter'||e.key===' '))e.preventDefault();if(e.key==='Escape')e.preventDefault();return;}if(page!=='play'||phase!=='play'||paused||e.ctrlKey||e.metaKey||e.altKey)return;if(['BUTTON','SELECT','SUMMARY','A','TEXTAREA'].includes(e.target?.tagName))return;if(e.target?.tagName==='INPUT'&&e.target.type!=='text'&&e.target.type!=='')return;const i=alternating()?turn:focused;if(!enabled(i))return;if(e.key==='Enter'){e.preventDefault();if(runs[i].feedback)next(i);else submit(i);}else if(/^[a-zA-Z'-]$/.test(e.key)||e.key==='Backspace'){e.preventDefault();runs[i].key(e.key);refreshAnswer(i);}}
 function frame(now){if(disposed)return;const dt=Math.min(250,Math.max(0,now-last));last=now;if(page==='play'&&phase==='play'&&!paused){runs.forEach((r,i)=>{if(enabled(i)){const hadFeedback=!!r.feedback;r.update(dt);if(!hadFeedback&&r.feedback)showFeedback(i,r.feedback);}});updateHud();if(runs.every(r=>r.done))finish();else if(shared()&&runs[turn].done){turn=1-turn;showTurns();refresh(turn);}}raf=requestAnimationFrame(frame);}

 const hidden=()=>{if(document.hidden)pause(true);};document.addEventListener('keydown',key);document.addEventListener('visibilitychange',hidden);if(initialPage==='records')records();else setup();raf=requestAnimationFrame(frame);return()=>{disposed=true;gate.dispose();cancelAnimationFrame(raf);speech.dispose();sound.dispose();destroyBoards();document.removeEventListener('keydown',key);document.removeEventListener('visibilitychange',hidden);muteBackground(false);};
}
